diff --git a/packages/excalidraw/utils/sanitize.ts b/packages/excalidraw/utils/sanitize.ts
index 1234567..abcdefg 100644
--- a/packages/excalidraw/utils/sanitize.ts
+++ b/packages/excalidraw/utils/sanitize.ts
@@ -0,0 +1,45 @@
+/**
+ * Sanitization utilities for preventing XSS attacks
+ */
+
+/**
+ * Escapes HTML special characters in a string for safe use in HTML attributes
+ */
+export const escapeAttribute = (str: string): string => {
+  return str
+    .replace(/&/g, "&amp;")
+    .replace(/</g, "&lt;")
+    .replace(/>/g, "&gt;")
+    .replace(/"/g, "&quot;")
+    .replace(/'/g, "&#x27;")
+    .replace(/\//g, "&#x2F;");
+};
+
+/**
+ * Sanitizes HTML content for safe use in iframe srcdoc
+ * Removes potentially dangerous elements and attributes while preserving
+ * safe formatting
+ */
+export const sanitizeHTML = (html: string): string => {
+  // Create a temporary container to parse and sanitize
+  const temp = document.createElement("div");
+  temp.textContent = html;
+  return temp.innerHTML;
+};
+
+/**
+ * Parses embed content and constructs srcdoc manually rather than
+ * using raw user input
+ */
+export const constructSafeSrcDoc = (
+  content: string,
+  options?: { allowScripts?: boolean }
+): string => {
+  const escapedContent = escapeAttribute(content);
+  
+  return `<!DOCTYPE html>
+<html>
+<head>
+  <meta http-equiv="Content-Security-Policy" content="default-src 'self' 'unsafe-inline' 'unsafe-eval' data: blob:; script-src 'self' 'unsafe-inline' 'unsafe-eval' data: blob:; frame-src *; img-src * data: blob:;">
+  <style>
+    body { margin: 0; overflow: hidden; background: transparent; }
+    html, body { height: 100%; }
+  </style>
+</head>
+<body>
+  <iframe srcdoc="${escapedContent}" style="width: 100%; height: 100%; border: none;"></iframe>
+</body>
+</html>`;
+};

