+mod certificate {
+    use crate::error::{Result, Error};
+    
+    pub struct ChainVerifier {
+        root_certs: Vec<Certificate>,
+        intermediate_certs: Vec<Certificate>,
+    }
+    
+    impl ChainVerifier {
+        pub fn new() -> Self {
+            Self {
+                root_certs: Vec::new(),
+                intermediate_certs: Vec::new(),
+            }
+        }
+        
+        pub fn with_root_certs(mut self, certs: &[Vec<u8>]) -> Self {
+            self.root_certs = certs.iter()
+                .filter_map(|c| Certificate::parse_der(c).ok())
+                .collect();
+            self
+        }
+        
+        pub fn with_intermediate_certs(mut self, chain: &[Vec<u8>]) -> Result<Self> {
+            self.intermediate_certs = chain.iter()
+                .filter_map(|c| Certificate::parse_der(c).ok())
+                .collect();
+            Ok(self)
+        }
+        
+        pub fn verify(&self, signature: &[u8], data: &[u8]) -> Result<bool> {
+            // Build and verify certificate chain
+            let mut trust_store = TrustStore::new();
+            for cert in &self.root_certs {
+                trust_store.add_trusted_cert(cert)?;
+            }
+            
+            let chain = CertificateChain::from_certs(&self.intermediate_certs)?;
+            chain.verify(&trust_store, signature, data)
+        }
+    }
