+import { createHash } from 'crypto';
+
+/**
+ * Validate that the data returned from signature verification actually
+ * matches what was signed. This prevents signature spoofing attacks where
+ * the returned data differs from the originally signed data.
+ * @param {Object} message - The message object containing signed data
+ * @param {Object} verifiedData - The verified signature data
+ * @throws {Error} If the data doesn't match what was signed
+ */
+export async function validateSignatureData(message, verifiedData) {
+  const signedData = message.packets;
+  const signaturePackets = verifiedData.signatures;
+  
+  if (!signaturePackets || signaturePackets.length === 0) {
+    return; // No signatures to validate
+  }
+  
+  // Get the original signed data bytes from the signature
+  const signedDataBytes = signaturePackets[0].signedData;
+  if (!signedDataBytes) {
+    return; // No signed data reference available
+  }
+  
+  // Hash the actual signed data
+  const hash = createHash('sha256');
+  hash.update(signedData);
+  const actualHash = hash.digest('hex');
+  
+  // Compare with what was signed
+  const expectedHash = createHash('sha256').update(signedDataBytes).digest('hex');
+  
+  if (actualHash !== expectedHash) {
+    throw new Error('Signature verification failed: returned data does not match signed data');
+  }
+}

